const crypto = require('crypto');
const secret = process.env.POS_RECOVERY_SHARED_SECRET;
const headers = $input.item.json.headers || {};
const body = $input.item.json.body || {};
const timestamp = headers['x-pos-recovery-timestamp'];
const requestId = headers['x-pos-recovery-request-id'];
const providedSig = String(headers['x-pos-recovery-signature'] || '').replace('sha256=', '');
const now = Date.now();
const withinWindow = Math.abs(now - Number(timestamp)) <= 5 * 60 * 1000;
const canonical = ['v1', body.store_id, timestamp, requestId, body.due_at || ''].join('\n');
const expected = crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');
const a = Buffer.from(expected, 'hex');
const b = Buffer.from(providedSig, 'hex');
const validSig = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!secret || !withinWindow || !validSig) {
  return [{ json: { _valid: false } }];
}
return [{ json: { _valid: true, store_id: body.store_id, original_due_at: body.due_at, stage: body.stage, _loopCount: 0 } }];

const crypto = require('crypto');
const secret = process.env.POS_RECOVERY_SHARED_SECRET;
const canonical = ['v1', $json.store_id, $json.timestamp, $json.request_id, ''].join('\n');
const signature = crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');
return [{ json: { ...$json, signature } }];

const context = $('組新的 request_id + timestamp').item.json;
const processorResult = $input.item.json;
return [{ json: {
  store_id: context.store_id,
  stage: context.stage,
  _loopCount: context._loopCount + 1,
  processor_result: processorResult
} }];
